import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [matches, setMatches] = useState([]);
  const [activeTab, setActiveTab] = useState('discover');
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [interests, setInterests] = useState([]);
  const [serverStatus, setServerStatus] = useState('checking');
  const [phoneNumber, setPhoneNumber] = useState('0712345678');

  // ============================================
  // API DEFINITIONS - EXACT MATCHING YOUR SPECS
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Activate Service',
      subtitle: 'Start your dating journey',
      icon: '💑',
      endpoint: '/activate',
      method: 'POST',
      body: { "penzi": "penzi" },
      requiresPhone: false,
      responseMessage: 'Welcome to our dating service with 6000 potential dating partners!'
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      endpoint: '/register',
      method: 'POST',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel', required: true },
        { key: 'name', label: '👤 Full Name', placeholder: 'John Doe', required: true },
        { key: 'age', label: '🎂 Age', placeholder: '26', type: 'number', required: true },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'], required: true },
        { key: 'county', label: '📍 County', placeholder: 'Nakuru', required: true },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Naivasha', required: true }
      ],
      requiresPhone: false,
      buildBody: (data) => ({
        phone_number: data.phone_number,
        name: data.name,
        age: data.age,
        gender: data.gender,
        county: data.county,
        town: data.town
      })
    },
    {
      id: 3,
      title: 'Complete Profile',
      subtitle: 'Add your details',
      icon: '📋',
      endpoint: '/{phone}/complete-profile',
      method: 'POST',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'], required: true },
        { key: 'profession', label: '💼 Profession', placeholder: 'Nurse', required: true },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'], required: true },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Christian', required: true },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Kisii', required: true }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        education_level: data.education_level,
        profession: data.profession,
        marital_status: data.marital_status,
        religion: data.religion,
        ethnicity: data.ethnicity
      })
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      endpoint: '/{phone}/self-description',
      method: 'POST',
      inputType: 'textarea',
      inputLabel: 'Describe yourself',
      inputPlaceholder: 'e.g., Hardworking, honest, family-oriented, loves nature',
      requiresPhone: true,
      buildBody: (data) => ({
        description: data.description
      })
    },
    {
      id: 5,
      title: 'Search Matches',
      subtitle: 'Find your perfect match',
      icon: '❤️',
      endpoint: '/sms',
      method: 'POST',
      fields: [
        { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', required: true },
        { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', required: true }
      ],
      requiresPhone: true,
      buildBody: (data) => ({
        phone_number: data.phone_number,
        message: `match#${data.age_range}#${data.town}`
      })
    }
  ];

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setSmsConversation(parsed.smsConversation || []);
        setPhoneNumber(parsed.phoneNumber || '0712345678');
        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        phoneNumber
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, phoneNumber]);

  // ============================================
  // CHECK SERVER CONNECTION
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
        console.log('✅ Server connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
      console.error('❌ Server connection failed:', error);
    }
  };

  // ============================================
  // HELPER FUNCTIONS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
    }
  };

  // ============================================
  // EXECUTE API - CORRECT IMPLEMENTATION
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      // Get phone number from form data or state
      let phone = formData.phone_number || phoneNumber || '0712345678';

      // Build endpoint URL
      let endpoint = step.endpoint;
      if (step.requiresPhone) {
        endpoint = endpoint.replace('{phone}', phone);
      }

      const fullUrl = API_BASE + endpoint;
      console.log(`📡 API ${step.id}: ${step.method} ${fullUrl}`);

      // Build request body
      let body = null;
      if (step.body) {
        body = step.body;
      } else if (step.buildBody) {
        body = step.buildBody(formData);
        // Ensure phone is included where needed
        if (step.requiresPhone && !body.phone_number) {
          body.phone_number = phone;
        }
      }

      console.log('📦 Request Body:', body);

      // Prepare fetch options
      const options = {
        method: step.method,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      };

      if (body && (step.method === 'POST' || step.method === 'PUT')) {
        options.body = JSON.stringify(body);
      }

      // Make the request
      const response = await fetch(fullUrl, options);
      console.log(`📥 Response Status: ${response.status}`);

      let responseData;
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        responseData = await response.json();
      } else {
        responseData = await response.text();
      }

      console.log('📥 Response Data:', responseData);

      // ============================================
      // HANDLE EACH API RESPONSE
      // ============================================

      if (response.ok) {
        // ---------- API 1: ACTIVATION ----------
        if (step.id === 1) {
          const message = responseData?.message || step.responseMessage;
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', message, true);
          setResponseMessage('✅ Service activated successfully!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated! Proceed to registration.');
          // Extract phone from welcome message or use default
          setPhoneNumber('0712345678');
        }

        // ---------- API 2: REGISTRATION ----------
        else if (step.id === 2) {
          const name = responseData?.data?.name || formData.name || 'User';
          const message = responseData?.message || `User registered successfully: ${name}`;

          // Build the SMS that was sent
          const smsSent = `start#${formData.name}#${formData.age}#${formData.gender}#${formData.county}#${formData.town}`;
          addToConversation('📱 You', smsSent, false);
          addToConversation('🤖 System', message, true);

          // Store phone number
          const phoneNum = formData.phone_number || '0712345678';
          setPhoneNumber(phoneNum);

          setResponseMessage('✅ ' + message);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 3.');
        }

        // ---------- API 3: COMPLETE PROFILE ----------
        else if (step.id === 3) {
          const message = responseData?.message || 'Profile completed successfully';

          const smsSent = `details#${formData.education_level}#${formData.profession}#${formData.marital_status}#${formData.religion}#${formData.ethnicity}`;
          addToConversation('📱 You', smsSent, false);
          addToConversation('🤖 System', message, true);

          setResponseMessage('✅ ' + message);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed! Proceed to step 4.');
        }

        // ---------- API 5: SELF-DESCRIPTION ----------
        else if (step.id === 4) {
          const message = responseData?.message || 'Self-description added successfully';

          const smsSent = `MYSELF ${formData.description}`;
          addToConversation('📱 You', smsSent, false);
          addToConversation('🤖 System', message, true);

          setResponseMessage('✅ ' + message);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete! Proceed to step 5.');
        }

        // ---------- API 6: MATCHING REQUEST ----------
        else if (step.id === 5) {
          const smsSent = `match#${formData.age_range}#${formData.town}`;
          addToConversation('📱 You', smsSent, false);

          // Extract matches from response
          let matchesData = [];
          if (responseData && responseData.matches) {
            matchesData = responseData.matches;
          } else if (responseData && responseData.data && responseData.data.matches) {
            matchesData = responseData.data.matches;
          } else {
            // Sample matches for demo
            matchesData = [
              { name: 'Grace Muthoni', age: 28, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
              { name: 'James Ochieng', age: 32, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Ambitious and hardworking. Passionate about technology.' },
              { name: 'Faith Wanjiru', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Caring and dedicated. Loves children and education.' }
            ];
          }

          setMatches(matchesData);

          const message = responseData?.message || `Found ${matchesData.length} matches!`;
          addToConversation('🤖 System', message, true);

          setResponseMessage('✅ ' + message);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));

          // Login user
          const user = {
            phone: formData.phone_number || phoneNumber || '0712345678',
            name: formData.name || 'User'
          };
          setCurrentUser(user);
          setIsLoggedIn(true);
          addNotification(`🎉 Found ${matchesData.length} matches!`);
        }

      } else {
        // Handle error response
        const errorMsg = responseData?.message || responseData?.error || `Error ${response.status}`;
        setResponseMessage('❌ ' + errorMsg);
        setIsSuccess(false);
        setErrorDetails(`Status: ${response.status}`);
        addNotification(`❌ ${errorMsg}`, 'error');
      }

    } catch (error) {
      console.error('❌ API Error:', error);
      let errorMessage = 'Network Error';
      let errorDetail = '';

      if (error.message.includes('Failed to fetch')) {
        errorMessage = 'Cannot connect to the server.';
        errorDetail = `Make sure the backend is running at ${API_BASE}`;
      } else {
        errorMessage = error.message || 'An unknown error occurred.';
        errorDetail = 'Please check your connection and try again.';
      }

      setResponseMessage('❌ ' + errorMessage);
      setIsSuccess(false);
      setErrorDetails(errorDetail);
      addNotification(`❌ ${errorMessage}`, 'error');

    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;

    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION FLOW
  // ============================================

  const renderRegistrationFlow = () => {
    const step = STEPS[currentStep];
    const isFirstStep = currentStep === 0;
    const isLastStep = currentStep === STEPS.length - 1;

    // Build SMS preview for current step
    let previewSms = '';
    if (step.id === 2) {
      previewSms = `start#${formData.name || 'John Doe'}#${formData.age || '26'}#${formData.gender || 'Male'}#${formData.county || 'Nakuru'}#${formData.town || 'Naivasha'}`;
    } else if (step.id === 3) {
      previewSms = `details#${formData.education_level || 'Graduate'}#${formData.profession || 'Nurse'}#${formData.marital_status || 'single'}#${formData.religion || 'Christian'}#${formData.ethnicity || 'Kisii'}`;
    } else if (step.id === 4) {
      previewSms = `MYSELF ${formData.description || 'Your description here'}`;
    } else if (step.id === 5) {
      previewSms = `match#${formData.age_range || '26-30'}#${formData.town || 'Nairobi'}`;
    }

    return (
      <div className="registration-container">
        <div className="registration-card">
          {/* Header */}
          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          {/* Server Status */}
          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking Server...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {/* Progress */}
          <div className="progress-bar-container">
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
            </div>
            <span className="progress-text">{getProgress()}% Complete</span>
          </div>

          {/* SMS Conversation */}
          {renderSmsConversation()}

          {/* Step Info */}
          <div className="step-info-card">
            <div className="step-number">Step {currentStep + 1} of {STEPS.length}</div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>

          {/* Form */}
          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">

            {/* API 1: Activation - Special Input */}
            {isFirstStep && (
              <div className="activation-section">
                <div className="activation-hint">
                  <div className="hint-bubble">
                    <span className="hint-label">📱 To activate:</span>
                    <span className="hint-code">PENZI</span>
                  </div>
                </div>
                <div className="input-group">
                  <label>Enter Activation Code</label>
                  <input
                    type="text"
                    value={formData.penzi || ''}
                    onChange={(e) => handleInputChange('penzi', e.target.value)}
                    placeholder="Type PENZI"
                    className="input-field activation-input"
                    required
                  />
                </div>
              </div>
            )}

            {/* Phone Number Input for steps that need it */}
            {step.requiresPhone && !isFirstStep && (
              <div className="input-group">
                <label>📱 Your Phone Number</label>
                <input
                  type="text"
                  value={formData.phone_number || phoneNumber || ''}
                  onChange={(e) => handleInputChange('phone_number', e.target.value)}
                  placeholder="Enter your phone number"
                  className="input-field"
                  required
                />
              </div>
            )}

            {/* Step 2: Registration Fields */}
            {step.id === 2 && step.fields && (
              <div className="form-group">
                {step.fields.map((field) => (
                  <div key={field.key} className="field-group">
                    <label>{field.label}</label>
                    {field.type === 'select' ? (
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        required
                      >
                        <option value="">Select {field.label}</option>
                        {field.options.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    ) : (
                      <input
                        type={field.type || 'text'}
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                        className="input-field"
                        required
                      />
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Step 3: Complete Profile Fields */}
            {step.id === 3 && step.fields && (
              <div className="form-group">
                {step.fields.map((field) => (
                  <div key={field.key} className="field-group">
                    <label>{field.label}</label>
                    {field.type === 'select' ? (
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        required
                      >
                        <option value="">Select {field.label}</option>
                        {field.options.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    ) : (
                      <input
                        type={field.type || 'text'}
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                        className="input-field"
                        required
                      />
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Step 4: Self-Description Textarea */}
            {step.id === 4 && (
              <div className="input-group">
                <label>{step.inputLabel}</label>
                <textarea
                  value={formData.description || ''}
                  onChange={(e) => handleInputChange('description', e.target.value)}
                  placeholder={step.inputPlaceholder}
                  className="textarea-field"
                  rows={3}
                  required
                />
              </div>
            )}

            {/* Step 5: Search Matches Fields */}
            {step.id === 5 && step.fields && (
              <div className="form-group">
                {step.fields.map((field) => (
                  <div key={field.key} className="field-group">
                    <label>{field.label}</label>
                    <input
                      type="text"
                      value={formData[field.key] || ''}
                      onChange={(e) => handleInputChange(field.key, e.target.value)}
                      placeholder={field.placeholder}
                      className="input-field"
                      required
                    />
                  </div>
                ))}
              </div>
            )}

            {/* SMS Preview for non-activation steps */}
            {previewSms && !isFirstStep && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">{previewSms}</div>
              </div>
            )}

            {/* Action Buttons */}
            <div className="registration-actions">
              <button
                type="button"
                onClick={() => goToStep(currentStep - 1)}
                disabled={currentStep === 0 || isLoading}
                className="btn-secondary"
              >
                ⬅ Previous
              </button>

              <button
                type="submit"
                disabled={isLoading || serverStatus === 'error'}
                className={`btn-primary ${isLoading ? 'loading' : ''}`}
              >
                {isLoading ? '⏳ Processing...' : isFirstStep ? '💑 Activate Service' : '📤 Send SMS'}
              </button>

              <button
                type="button"
                onClick={() => goToStep(currentStep + 1)}
                disabled={isLastStep || isLoading || !completedSteps.has(currentStep)}
                className="btn-secondary"
              >
                Next ➡
              </button>
            </div>
          </form>

          {/* Error Details */}
          {errorDetails && (
            <div className="error-details">
              <p className="error-detail-text">💡 {errorDetails}</p>
            </div>
          )}

          {/* Response Message */}
          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          {/* Footer */}
          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================

  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (
          <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
            {notif.message}
          </div>
        ))}
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    const displayMatches = matches.length > 0 ? matches : [
      { name: 'Grace Muthoni', age: 28, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
      { name: 'James Ochieng', age: 32, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Ambitious and hardworking. Passionate about technology.' },
      { name: 'Faith Wanjiru', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Caring and dedicated. Loves children and education.' }
    ];

    const currentMatch = displayMatches[currentMatchIndex] || displayMatches[0];

    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="profile-btn" onClick={() => setShowProfile(!showProfile)}>👤</button>
          </div>
        </header>

        <nav className="dashboard-nav">
          <button className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} onClick={() => setActiveTab('discover')}>🔍 Discover</button>
          <button className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} onClick={() => setActiveTab('matches')}>💕 Matches</button>
          <button className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} onClick={() => setActiveTab('requests')}>📬 Requests</button>
          <button className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} onClick={() => setActiveTab('chat')}>💬 Chat</button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && (
            <div className="discover-container">
              <div className="match-card">
                <div className="match-card-header">
                  <div className="match-avatar">{currentMatch?.name?.charAt(0) || '?'}</div>
                  <div className="match-info">
                    <h3>{currentMatch?.name || 'Unknown'}</h3>
                    <p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p>
                  </div>
                </div>
                <div className="match-details">
                  <div className="detail-item"><span className="detail-label">💼 Profession</span><span className="detail-value">{currentMatch?.profession || 'Not specified'}</span></div>
                  <div className="detail-item"><span className="detail-label">🎓 Education</span><span className="detail-value">{currentMatch?.education || 'Not specified'}</span></div>
                  <div className="detail-item"><span className="detail-label">🙏 Religion</span><span className="detail-value">{currentMatch?.religion || 'Not specified'}</span></div>
                  <div className="detail-item"><span className="detail-label">🌍 Ethnicity</span><span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span></div>
                  {currentMatch?.description && (
                    <div className="detail-item full-width">
                      <span className="detail-label">💭 About Me</span>
                      <span className="detail-value description">{currentMatch.description}</span>
                    </div>
                  )}
                </div>
                <div className="match-actions">
                  <button className="btn-secondary" onClick={() => setShowMatchDetails(true)}>👤 View Profile</button>
                  <button className="btn-primary">💕 I'm Interested</button>
                </div>
                <div className="match-navigation">
                  <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))} disabled={currentMatchIndex === 0}>⬅ Previous</button>
                  <span className="match-counter">{currentMatchIndex + 1} of {displayMatches.length}</span>
                  <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.min(displayMatches.length - 1, currentMatchIndex + 1))} disabled={currentMatchIndex === displayMatches.length - 1}>Next ➡</button>
                </div>
              </div>
            </div>
          )}
          {activeTab === 'matches' && (
            <div className="empty-state">
              <div className="empty-icon">💕</div>
              <h2>No Matches Yet</h2>
              <p>Start discovering to find your match</p>
              <button className="btn-primary" onClick={() => setActiveTab('discover')}>Discover People</button>
            </div>
          )}
          {activeTab === 'requests' && (
            <div className="empty-state">
              <div className="empty-icon">📬</div>
              <h2>No Requests</h2>
              <p>When someone shows interest, you'll see it here</p>
            </div>
          )}
          {activeTab === 'chat' && (
            <div className="empty-state">
              <div className="empty-icon">💬</div>
              <h2>No Messages</h2>
              <p>Start a conversation with your matches</p>
            </div>
          )}
        </main>
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {renderNotifications()}
      {isLoggedIn ? renderDashboard() : renderRegistrationFlow()}
    </div>
  );
}

export default App;
